#[using="Type"] Lemma ext_Z_split : forall lo n n' z,
  ext_Z false lo (n + n') z = (ext_Z false lo n z + 2 ^ (8 * Z.of_nat n) * ext_Z false (lo + n) n' z)%Z.
Proof.
