#[using="Type"] Lemma ext_partner_sound : forall c lo n v ts n' r,
  ext_partner c lo n v ts = Some (n', r) ->
  (lo + n + n' <= 8)%nat /\ eqm (tden ts) (c * 2 ^ (8 * Z.of_nat n) * uE (EExt false (lo + n) n' v) + tden r).
Proof.
