#[using="Type"] Lemma lit_strip_val : forall E e v c,
  lit_strip e = (v, c) ->
  bv_unsigned (edenot E e) = ((bv_unsigned (edenot E v) + c) mod 2 ^ 64)%Z.
Proof.
