#[using="Type"] Lemma lowbits_sound : forall segs E M kn e j v,
  know_ok segs E M kn -> (0 <= j <= 64)%Z ->
  lowbits kn e j = Some v -> (bv_unsigned (edenot E e) mod 2 ^ j = v)%Z.
